package io.github.capozziv.digitalbanking.transfers.adapters.persistence

import com.fasterxml.uuid.Generators
import io.github.capozziv.digitalbanking.transfers.application.port.IdGenerator
import org.springframework.stereotype.Component
import java.util.UUID

/** Time-ordered UUID v7 ids, generated by the application before the row is written. */
@Component
class UuidV7IdGenerator : IdGenerator {
    private val generator = Generators.timeBasedEpochGenerator()

    override fun newId(): UUID = generator.generate()
}
